import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),i={name:"guide/troubleshooting.md"};function r(s,e,l,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="bootloop-bsod-after-enabling" tabindex="-1">Bootloop / BSOD after enabling <a class="header-anchor" href="#bootloop-bsod-after-enabling" aria-label="Permalink to &quot;Bootloop / BSOD after enabling&quot;">​</a></h2><p><strong>Option 1 — Android Safe Mode</strong></p><p>Boot into Safe Mode (hold Volume Down during boot on most devices). This disables all third-party modules. You can then open LSPosed and disable Weeabooify.</p><p><strong>Option 2 — Custom Recovery</strong></p><p>Boot into your custom recovery and delete the module:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/adb/modules/weeabooify/</span></span></code></pre></div><p>This removes the module without needing to boot into Android.</p><hr><h2 id="module-is-enabled-but-nothing-changes" tabindex="-1">Module is enabled but nothing changes <a class="header-anchor" href="#module-is-enabled-but-nothing-changes" aria-label="Permalink to &quot;Module is enabled but nothing changes&quot;">​</a></h2><ul><li>Make sure you selected <strong>both SystemUI and Framework</strong> in the LSPosed scope</li><li>Try tapping <strong>Reoptimize</strong> in LSPosed for the Weeabooify entry</li><li>Reboot after changing scope</li></ul><hr><h2 id="app-shows-not-logged-in-or-features-are-locked" tabindex="-1">App shows &quot;not logged in&quot; or features are locked <a class="header-anchor" href="#app-shows-not-logged-in-or-features-are-locked" aria-label="Permalink to &quot;App shows &quot;not logged in&quot; or features are locked&quot;">​</a></h2><p>The Full Version requires account login. Make sure you:</p><ol><li>Have registered an account (email)</li><li>Are logged in inside the Weeabooify app</li><li>Have a stable internet connection for the first login</li></ol><hr><h2 id="preferences-not-applying-to-systemui" tabindex="-1">Preferences not applying to SystemUI <a class="header-anchor" href="#preferences-not-applying-to-systemui" aria-label="Permalink to &quot;Preferences not applying to SystemUI&quot;">​</a></h2><p>This is typically a cross-process preference sync issue. Try:</p><ol><li>Toggling a setting off and back on</li><li>Force-stopping SystemUI via Developer Options</li><li>Rebooting the device</li></ol><hr><h2 id="continuous-crash-detected-safe-mode-triggered-on-clean-boot" tabindex="-1">&quot;Continuous crash detected&quot; safe mode triggered on clean boot <a class="header-anchor" href="#continuous-crash-detected-safe-mode-triggered-on-clean-boot" aria-label="Permalink to &quot;&quot;Continuous crash detected&quot; safe mode triggered on clean boot&quot;">​</a></h2><p>This is a known edge case when multiple SystemUI hooks each record a crash event. It resolves itself — simply reboot once and the safe mode flag clears. If it persists, contact support.</p><hr><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><p>Join the <a href="https://t.me/weeabooify" target="_blank" rel="noreferrer">Telegram community</a> or contact <a href="https://t.me/kaerushi" target="_blank" rel="noreferrer">@KaeruShi</a> directly.</p>',25)])])}const g=o(i,[["render",r]]);export{u as __pageData,g as default};
